#ifndef STDLIB_ML_BASE_KMEANS_RESULTS_FLOAT32_H
#define STDLIB_ML_BASE_KMEANS_RESULTS_FLOAT32_H

#include <stdbool.h>
#include <stdint.h>

/**
* Struct for storing kmeans clustering results.
*/
struct stdlib_ml_kmeans_float32_results {
	// Number of times the data was clustered with different initial centroids:
	int64_t replicates;

	// Index of the initial centroids which produced the best result:
	int64_t replicate;

	// Distance metric:
	int8_t metric;

	// Number of iterations for best results:
	int64_t iterations;

	// Clustering algorithm:
	int8_t algorithm;

	// Sum of squared distances to the closest centroid for all samples:
	float inertia;

	// Number of clusters:
	int64_t k;

	// Number of samples:
	int64_t samples;

	// Number of features:
	int64_t features;
};

#endif // !STDLIB_ML_BASE_KMEANS_RESULTS_FLOAT32_H
